import{text,list,identifiers,choice}from'../creative-kit/state.js?v=0.9.0';
export const VERDICTS={open:'Unexamined',try:'Possibly overlooked',reason:'Empty for a reason'};export const FIELDS=['title','mechanism','assumption','test'];export const cell=(need,method)=>`${need}|${method}`;
export function make(id='first',example='example'){const w={id,problem:example==='blank'?'':'Help people act usefully when a battery decision is uncertain.',needs:[{id:'n1',label:'Understand the situation'},{id:'n2',label:'Choose an action'},{id:'n3',label:'Learn for next time'}],methods:[{id:'m1',label:'Information'},{id:'m2',label:'Rehearsal'},{id:'m3',label:'Rules & limits'}],ideas:[],gaps:{},selected:'n1|m2'};if(example!=='blank')w.ideas=[{id:'i1',need:'n1',method:'m1',title:'Feed-age view',mechanism:'Make outdated information visible beside the decision.',assumption:'The actor knows when old information matters.',test:'Replay an outage and ask what the actor notices.'},{id:'i2',need:'n2',method:'m1',title:'Compare feasible actions',mechanism:'Show which options fit the known limits.',assumption:'The relevant limits can be made explicit.',test:'Compare two choices in a fictional dispatch scene.'},{id:'i3',need:'n2',method:'m3',title:'A reversible envelope',mechanism:'Permit bounded decisions until conditions leave an agreed envelope.',assumption:'There are observable boundaries and a clear owner.',test:'Classify sample decisions before seeing outcomes.'},{id:'i4',need:'n3',method:'m2',title:'Rehearse a difficult handoff',mechanism:'Let two roles practise the transfer of a consequential decision.',assumption:'Rehearsal reveals missing context.',test:'Observe what each person knows before and after.'}];return w;}
export function validate(w){for(const key of['needs','methods']){list(w[key],6);if(!w[key].length)throw Error('Keep at least one axis item.');identifiers(w[key]);w[key].forEach(x=>text(x.label));}list(w.ideas,30);identifiers(w.ideas);for(const i of w.ideas){FIELDS.forEach(f=>text(i[f]));if(i.need!==null&&!w.needs.some(x=>x.id===i.need)||i.method!==null&&!w.methods.some(x=>x.id===i.method))throw Error('Idea points outside the map.');}const valid=new Set(w.needs.flatMap(n=>w.methods.map(m=>cell(n.id,m.id))));if(!valid.has(w.selected))throw Error('Selected cell is missing.');if(!w.gaps||typeof w.gaps!=='object'||Array.isArray(w.gaps))throw Error('Invalid gap notes.');for(const[key,g]of Object.entries(w.gaps)){if(!valid.has(key))throw Error('A gap note points outside the map.');choice(g.verdict,Object.keys(VERDICTS));text(g.reason);}return w;}
export function apply(w,a){if(a.type==='edit'){if(a.collection==='ideas'){const i=w.ideas.find(i=>i.id===a.item);if(!i)throw Error('Idea is missing.');choice(a.field,FIELDS);i[a.field]=text(a.value);}else if(['needs','methods'].includes(a.collection)){const x=w[a.collection].find(x=>x.id===a.item);if(!x)throw Error('Axis item is missing.');choice(a.field,['label']);x.label=text(a.value);}else if(a.collection==='gap'){const g=w.gaps[w.selected]??={verdict:'open',reason:''};choice(a.field,['verdict','reason']);g[a.field]=a.field==='verdict'?choice(a.value,Object.keys(VERDICTS)):text(a.value);}else throw Error('Unknown field.');}else if(a.type==='select')w.selected=a.cell;else if(a.type==='move'){const i=w.ideas.find(i=>i.id===a.id);if(!i)throw Error('Idea is missing.');if(a.cell==='unplaced'){i.need=null;i.method=null;}else[i.need,i.method]=a.cell.split('|');}else if(a.type==='add-idea'){const[need,method]=a.cell?a.cell.split('|'):[null,null];w.ideas.push({id:a.id,need,method,title:'New possibility',mechanism:'',assumption:'',test:''});}else if(a.type==='remove-idea')w.ideas=w.ideas.filter(i=>i.id!==a.id);else if(a.type==='add-axis'){choice(a.axis,['needs','methods']);w[a.axis].push({id:a.id,label:'New axis'});}else throw Error('Unknown territory action.');}
export function markdown(w){return['# Unexplored territory','',w.problem,'',...w.ideas.flatMap(i=>[`## ${i.title}`,'',`Need: ${w.needs.find(n=>n.id===i.need)?.label||'Unplaced'} · Mechanism: ${w.methods.find(m=>m.id===i.method)?.label||'Unplaced'}`,'',...FIELDS.slice(1).flatMap(f=>[`**${f}**`,i[f]||'_Not written._',''])]),'## Examined gaps','',...Object.entries(w.gaps).flatMap(([key,g])=>{const[n,m]=key.split('|');return[`### ${w.needs.find(x=>x.id===n).label} × ${w.methods.find(x=>x.id===m).label}`,VERDICTS[g.verdict],g.reason,''];})].join('\n');}
